// Custom sampler stubs (mapped to noise texture)
#define sampler_lavatex sampler_noise_lq
sampler sampler_lavatex;
# define t uTime;
# define MaxSteps 1000 // max steps for ray marching
const float spaceshipxzspeed = q23;
const float spaceship2xzspeed = q15;
const float cameraxzspeed = q22;
const vec3 cubesize = vec3(0.1,0.1,1.1);
const vec3 torus1pos = vec3( 0.0 , 0.0 , 0.0 );
const vec2 torus1size = vec2(30.2,5.6);
const float torus1rotspeed = q13;
//const float torus1rotspeed = uTime;
const vec3 camerapos = vec3(q19, q20, q21);
const vec3 cameralookat = vec3(q16,q17,q18);
const vec3 LightPos = camerapos + vec3( 0.0 , 0.0 ,q28);
float dBox(vec3 p, vec3 s)
{
return length(max(abs(p)-s, 0.));
}
float sdTorus(vec3 p, vec2 r) {
float x = length(p.xz)-r.x;
return q14*(length(vec2(x, p.y))-r.y);
}
float sdSphere( vec3 p, float s )
{
return length(p)-s;
}
vec3 RotX (vec3 p, float speed)
{
return vec3(p.x, p.y*cos(speed) + p.z*-sin(speed),  p.y*sin(speed) + p.z*cos(speed));
}
vec3 RotY (vec3 p, float speed)
{
return vec3(p.x*cos(speed) + p.z*sin(speed), p.y, p.x*-sin(speed) + p.z*cos(speed));
}
vec3 RotZ (vec3 p, float speed)
{
return vec3(p.x*cos(speed)  + p.y*-sin(speed), p.x*sin(speed) + p.y*cos(speed), p.z);
}
vec2 GetDist(vec3 p)
{
vec3 pnew = p;
pnew = RotZ(pnew, torus1rotspeed);
float td = sdTorus(pnew + torus1pos + vec3( 30.0 , 0.0 , 0.0 ), torus1size);
vec2 toreturn = vec2(td, 1.0 );
return toreturn;
}
vec3 RayMarch(vec3 ro, vec3 rd)
{
vec2 dS;
float dO;
vec3 p;
float breakloop = 0;
for(int i = 0; i<MaxSteps && breakloop == 0; i++)
{
p = ro + rd * dO;
dS = GetDist(p);
if(dS.x < 0.0001) {breakloop = 1; }
dO += dS.x;
}
return vec3(dO,dS);
}
float dist(vec2 a, vec2 b)
{
return sqrt(pow(a.x-b.x, 2.0 ) + pow(a.y-b.y, 2.0 ));
}
vec3 toruscol(vec3 p, vec3 tpos, float rotspeed)
{
vec3 col = 0;
float x = atan(p.x + tpos.x, p.z + tpos.z) - 0.0*rotspeed -0.3*cameraxzspeed;
float y = atan(length(p.xz + tpos.xz)-torus1size.x, p.y + tpos.y);
vec3 tex = texture(sampler_lavatex, vec2(x,y) * 5.0);
float bands = abs(sin(y * 5.0));
float ripples = sin((x * 8.0-y * 1.0) * 5.0 + 0.0 * q5*0.3 + 0.0 * uTime * 5.0)*0.5 + 0.5;
float waves = sin(x * 4.0 + 0.0 * y * 6.0 + q5*0.1 + 2.0 * uTime);
float b1 = smoothstep(-.5, .5, bands);
float b2 = smoothstep(-.5, .5, bands-.5)*tex.x;
float m = b1*(1.0 - b2);
m = max(m, ripples*b2*max( 0.0 ,waves * 10.0));
col = m;
col *= vec3(m*1.1, 1.2, 1.6);
//col = bands;
return col*0.25;
}
vec3 GetNormal(vec3 p)
{
float d = GetDist(p).x;
vec2 e = vec2(.01, 0.0 );
vec3 n = d-vec3(GetDist(p-e.xyy).x,
GetDist(p-e.yxy).x,
GetDist(p-e.yyx).x);
return normalize(n);
}
float GetLight(vec3 p)
{
vec3 lightpos = LightPos;
//lightpos = camerapos;
vec3 l = normalize(lightpos - p);
vec3 n = GetNormal(p);
float dif = clamp(dot(n, l*q25), 0., 1.);
//dif = dot(n,l);
float d = RayMarch(p + n*0.2, l);
if(d < length(lightpos-p)) {dif *= q24;}
return dif;
}
shader_body
{
uv-= 0.5;
uv.y*=-1;
uv *= uAspect.xy;
float rotspeed = 0;
rotspeed = 0.015*q5 + uTime*0.1;
//uv = vec2(cos(rotspeed)*uv.x - sin(rotspeed)*uv.y, sin(rotspeed)*uv.x + cos(rotspeed)*uv.y);
float beat = q32;
vec3 col = 0;
vec3 lookat = cameralookat;
float zoom = 0.3;
vec3 ro = camerapos;
vec3 F = normalize(lookat-ro); // Forward
vec3 R = normalize(cross(vec3(0., 1., 0.), F)); //Right
vec3 U = cross(F, R); //Up
vec3 C = ro + F*zoom;
vec3 I = C + uv.x*R + uv.y*U;
vec3 rd = normalize(I-ro);
vec3 d = RayMarch(ro,rd);
vec3 p = ro + rd*d.x;
float dif = GetLight(p); //***
vec3 pnew = p;
pnew = RotZ(pnew, torus1rotspeed);
if(d.z == 1)
{
ret = toruscol(pnew, torus1pos + vec3( 30.0 , 0.0 , 0.0 ), rotspeed);
ret *= dif; //***
}
//ret = dif;
//ret = GetNormal(p);
}

