sampler sampler_seaweed;
shader_body
{
//vec2 uv1 = uv-.5;
vec3 ret1 = texture(sampler_main, uv) +texture(sampler_main, 1.0 - uv) * 0.0;
vec2 uv1 = uv*1. + uTime*0.; //0.3;
vec2 dz = vec2(0.05, 0.37);
uv1 = .25*cos(uv1 + 4.96 + uTime*.5) -2.*dz;;
vec3 dots = 0.1 + clamp(0., 1., .03/length(uv1) ) ;
ret1 = (-ret1/5.) + 6.*dots*(-0.08+ret1);
ret = ret1 * 5.0;
vec2 texc = 0.4 + 0.6*ret.xy;
vec3 col = vec3(2.2,1.2,1.3 + 0.3*sin(uTime));
vec3 ret3;
vec3 ret4;
vec3 aa = texture(sampler_seaweed, texc);
aa.x *= col.x;
aa.y *= col.y;
aa.z *= col.z;
aa.xyz -= 0.45;
//aa.x += q1;
//aa.y += q2;
//aa.z += q3;
ret3 = ret * aa * GetBlur3(uv) * 10.0;
aa = texture(sampler_seaweed, texc);
aa.x *= col.z;
aa.y *= col.x;
aa.z *= col.y;
aa.x -= 0.95;
aa.y += 0.1;
aa.z += 3.7;
ret4 = ret * aa * GetBlur3(uv) * 20.0;
ret4 *= 0.03;
ret = mix(ret3, ret4, (q1 + q2 + q3)*0.7);
//ret = ret4;
//ret = ret3;
//ret = ret3;
//ret = ret3;
}

