vec3 GetNormal(vec3 p)
{
float d = GetDist(p).x;
vec2 e = vec2(.01, 0.0 );
vec3 n = d-vec3(GetDist(p-e.xyy).x,
GetDist(p-e.yxy).x,
GetDist(p-e.yyx).x);
return normalize(n);
