float GetLight(vec3 p)
{
vec3 lightpos = LightPos;
//lightpos = camerapos;
vec3 l = normalize(lightpos - p);
vec3 n = GetNormal(p);
float dif = clamp(dot(n, l*q25), 0., 1.);
//dif = dot(n,l);
float d = RayMarch(p + n*0.2, l);
if(d < length(lightpos-p)) {dif *= q24;}
return dif;
}
